public int[] findLongest(CharSequence query, int start)
    {
        if ((query == null) || (start >= query.length()))
        {
            return new int[]{0, -1};
        }
        int state = 1;
        int maxLength = 0;
        int lastVal = -1;
        for (int i = start; i < query.length(); i++)
        {
            int[] res = transferValues(state, query.charAt(i));
            if (res[0] == -1)
            {
                break;
            }
            state = res[0];
            if (res[1] != -1)
