				.appendln(algorithm.getUsage());
		}

		strBuilder
			.appendNewLine()
			.appendln("Available outputs:");

		for (Output output : outputFactory) {
			strBuilder
				.append("  --output ")
				.append(output.getName())
				.append(" ")
				.appendln(output.getUsage());
		}

		return strBuilder
			.appendNewLine()
			.toString();
