			throw new IllegalArgumentException();
		}

		mDestJarName = destJar.getCanonicalPath();
		FileOutputStream fout = new FileOutputStream(destJar);
		JarOutputStream jout = new JarOutputStream(fout);
		//jout.setLevel(0);
		try {
			jarDir(dirOrFile2Jar, jout, null);
