@Override
	public int next(int bits) {
		long nextSeed = seed ^ (seed << 21);
		nextSeed ^= (nextSeed >>> 35);
		nextSeed ^= (nextSeed << 4);
		seed = nextSeed;
		return (int) (nextSeed & ((1L << bits) - 1));
	}

