public W addWindow(W newWindow, MergeFunction<W> mergeFunction) throws Exception {

		List<W> windows = new ArrayList<>();

		windows.addAll(this.mapping.keySet());
		windows.add(newWindow);

		final Map<W, Collection<W>> mergeResults = new HashMap<>();
		windowAssigner.mergeWindows(windows,
				new MergingWindowAssigner.MergeCallback<W>() {
					@Override
					public void merge(Collection<W> toBeMerged, W mergeResult) {
						if (LOG.isDebugEnabled()) {
							LOG.debug("Merging {} into {}", toBeMerged, mergeResult);
						}
						mergeResults.put(mergeResult, toBeMerged);
					}
				});

		W resultWindow = newWindow;
		boolean mergedNewWindow = false;

		// perform the merge
		for (Map.Entry<W, Collection<W>> c: mergeResults.entrySet()) {
			W mergeResult = c.getKey();
			Collection<W> mergedWindows = c.getValue();

			// if our new window is in the merged windows make the merge result the
			// result window
			if (mergedWindows.remove(newWindow)) {
				mergedNewWindow = true;
				resultWindow = mergeResult;
			}

			// pick any of the merged windows and choose that window's state window
			// as the state window for the merge result
			W mergedStateWindow = this.mapping.get(mergedWindows.iterator().next());

			// figure out the state windows that we are merging
			List<W> mergedStateWindows = new ArrayList<>();
			for (W mergedWindow: mergedWindows) {
				W res = this.mapping.remove(mergedWindow);
				if (res != null) {
					mergedStateWindows.add(res);
				}
			}

			this.mapping.put(mergeResult, mergedStateWindow);

			// don't put the target state window into the merged windows
			mergedStateWindows.remove(mergedStateWindow);

			// don't merge the new window itself, it never had any state associated with it
			// i.e. if we are only merging one pre-existing window into itself
			// without extending the pre-existing window
			if (!(mergedWindows.contains(mergeResult) && mergedWindows.size() == 1)) {
				mergeFunction.merge(mergeResult,
						mergedWindows,
						this.mapping.get(mergeResult),
						mergedStateWindows);
			}
		}

		// the new window created a new, self-contained window without merging
		if (mergeResults.isEmpty() || (resultWindow.equals(newWindow) && !mergedNewWindow)) {
			this.mapping.put(resultWindow, resultWindow);
		}

		return resultWindow;
	}

@Override
	public DataSet<Result<K>> runInternal(Graph<K, VV, EV> input)
			throws Exception {
		// u, v where u < v
		DataSet<Tuple2<K, K>> filteredByID = input
			.getEdges()
			.flatMap(new FilterByID<>())
				.setParallelism(parallelism)
				.name("Filter by ID");

		// u, v, (edge value, deg(u), deg(v))
		DataSet<Edge<K, Tuple3<EV, LongValue, LongValue>>> pairDegree = input
			.run(new EdgeDegreePair<K, VV, EV>()
				.setParallelism(parallelism));

		// u, v where deg(u) < deg(v) or (deg(u) == deg(v) and u < v)
		DataSet<Tuple2<K, K>> filteredByDegree = pairDegree
			.flatMap(new FilterByDegree<>())
				.setParallelism(parallelism)
				.name("Filter by degree");

		// u, v, w where (u, v) and (u, w) are edges in graph, v < w
		DataSet<Tuple3<K, K, K>> triplets = filteredByDegree
			.groupBy(0)
			.sortGroup(1, Order.ASCENDING)
			.reduceGroup(new GenerateTriplets<>())
				.name("Generate triplets");

		// u, v, w where (u, v), (u, w), and (v, w) are edges in graph, v < w
		DataSet<Result<K>> triangles = triplets
			.join(filteredByID, JoinOperatorBase.JoinHint.REPARTITION_HASH_SECOND)
			.where(1, 2)
			.equalTo(0, 1)
			.with(new ProjectTriangles<>())
				.name("Triangle listing");

		if (permuteResults) {
			triangles = triangles
				.flatMap(new PermuteResult<>())
					.name("Permute triangle vertices");
		} else if (sortTriangleVertices.get()) {
			triangles = triangles
				.map(new SortTriangleVertices<>())
					.name("Sort triangle vertices");
		}

		return triangles;
	}

public final Object accessField(Field field, Object object) {
		try {
			object = field.get(object);
		} catch (NullPointerException npex) {
			throw new NullKeyFieldException("Unable to access field "+field+" on object "+object);
		} catch (IllegalAccessException iaex) {
			throw new RuntimeException("This should not happen since we call setAccesssible(true) in PojoTypeInfo."
			+ " fields: " + field + " obj: " + object);
		}
		return object;
	}

public org.apache.hadoop.conf.Configuration getOrLoadHadoopConfig() {
		org.apache.hadoop.conf.Configuration hadoopConfig = this.hadoopConfig;
		if (hadoopConfig == null) {
			if (flinkConfig != null) {
				hadoopConfig = mirrorCertainHadoopConfig(loadHadoopConfigFromFlink());
			}
			else {
				LOG.warn("Flink configuration is not set prior to loading this configuration."
					+ " Cannot forward configuration keys from Flink configuration.");
				hadoopConfig = new org.apache.hadoop.conf.Configuration();
			}
		}
		this.hadoopConfig = hadoopConfig;
		return hadoopConfig;
	}

private org.apache.hadoop.conf.Configuration loadHadoopConfigFromFlink() {
		org.apache.hadoop.conf.Configuration hadoopConfig = new org.apache.hadoop.conf.Configuration();
		for (String key : flinkConfig.keySet()) {
			for (String prefix : flinkConfigPrefixes) {
				if (key.startsWith(prefix)) {
					String newKey = hadoopConfigPrefix + key.substring(prefix.length());
					String newValue = fixHadoopConfig(key, flinkConfig.getString(key, null));
					hadoopConfig.set(newKey, newValue);

					LOG.debug("Adding Flink config entry for {} as {} to Hadoop config", key, newKey);
				}
			}
		}
		return hadoopConfig;
	}

private org.apache.hadoop.conf.Configuration mirrorCertainHadoopConfig(
		org.apache.hadoop.conf.Configuration hadoopConfig) {
		for (String[] mirrored : mirroredConfigKeys) {
			String value = hadoopConfig.get(mirrored[0], null);
			if (value != null) {
				hadoopConfig.set(mirrored[1], value);
			}
		}
		return hadoopConfig;
	}

private static void safelyTruncateFile(
			final FileSystem fileSystem,
			final Path path,
			final HadoopFsRecoverable recoverable) throws IOException {

		ensureTruncateInitialized();

		waitUntilLeaseIsRevoked(fileSystem, path);

		// truncate back and append
		boolean truncated;
		try {
			truncated = truncate(fileSystem, path, recoverable.offset());
		} catch (Exception e) {
			throw new IOException("Problem while truncating file: " + path, e);
		}

		if (!truncated) {
			// Truncate did not complete immediately, we must wait for
			// the operation to complete and release the lease.
			waitUntilLeaseIsRevoked(fileSystem, path);
		}
	}

private static boolean waitUntilLeaseIsRevoked(final FileSystem fs, final Path path) throws IOException {
		Preconditions.checkState(fs instanceof DistributedFileSystem);

		final DistributedFileSystem dfs = (DistributedFileSystem) fs;
		dfs.recoverLease(path);

		final Deadline deadline = Deadline.now().plus(Duration.ofMillis(LEASE_TIMEOUT));

		final StopWatch sw = new StopWatch();
		sw.start();

		boolean isClosed = dfs.isFileClosed(path);
		while (!isClosed && deadline.hasTimeLeft()) {
			try {
				Thread.sleep(500L);
			} catch (InterruptedException e1) {
				throw new IOException("Recovering the lease failed: ", e1);
			}
			isClosed = dfs.isFileClosed(path);
		}
		return isClosed;
	}

public static KvStateClientProxy createKvStateClientProxy(
			final InetAddress address,
			final Iterator<Integer> ports,
			final int eventLoopThreads,
			final int queryThreads,
			final KvStateRequestStats stats) {

		Preconditions.checkNotNull(address, "address");
		Preconditions.checkNotNull(stats, "stats");

		Preconditions.checkArgument(eventLoopThreads >= 1);
		Preconditions.checkArgument(queryThreads >= 1);

		try {
			String classname = "org.apache.flink.queryablestate.client.proxy.KvStateClientProxyImpl";
			Class<? extends KvStateClientProxy> clazz = Class.forName(classname).asSubclass(KvStateClientProxy.class);
			Constructor<? extends KvStateClientProxy> constructor = clazz.getConstructor(
					InetAddress.class,
					Iterator.class,
					Integer.class,
					Integer.class,
					KvStateRequestStats.class);
			return constructor.newInstance(address, ports, eventLoopThreads, queryThreads, stats);
		} catch (ClassNotFoundException e) {
			final String msg = "Could not load Queryable State Client Proxy. " + ERROR_MESSAGE_ON_LOAD_FAILURE;
			if (LOG.isDebugEnabled()) {
				LOG.debug(msg + " Cause: " + e.getMessage());
			} else {
				LOG.info(msg);
			}
			return null;
		} catch (InvocationTargetException e) {
			LOG.error("Queryable State Client Proxy could not be created: ", e.getTargetException());
			return null;
		} catch (Throwable t) {
			LOG.error("Failed to instantiate the Queryable State Client Proxy.", t);
			return null;
		}
	}

