@Override
	public T next(T target) throws IOException {
		// check for the left over element
		if (this.readPhase) {
			return getNextRecord(target);
		} else {
			// writing phase. check for leftover first
			if (this.leftOverReturned) {
				// get next record
				if ((target = this.input.next(target)) != null) {
					if (writeNextRecord(target)) {
						return target;
					} else {
						// did not fit into memory, keep as leftover
						this.leftOverRecord = this.serializer.copy(target, this.leftOverRecord);
						this.leftOverReturned = false;
						this.fullWriteBuffer = true;
						return null;
					}
				} else {
					this.noMoreBlocks = true;
					return null;
				}
			} else if (this.fullWriteBuffer) {
				return null;
			} else {
				this.leftOverReturned = true;
				target = this.serializer.copy(this.leftOverRecord, target);
				return target;
			}
		}
	}

@Override
	public void computeUnclosedBranchStack() {
		if (this.openBranches != null) {
			return;
		}

		addClosedBranches(getPredecessorNode().closedBranchingNodes);
		List<UnclosedBranchDescriptor> fromInput = getPredecessorNode().getBranchesForParent(this.inConn);

		// handle the data flow branching for the broadcast inputs
		List<UnclosedBranchDescriptor> result = computeUnclosedBranchStackForBroadcastInputs(fromInput);

		this.openBranches = (result == null || result.isEmpty()) ? Collections.<UnclosedBranchDescriptor>emptyList() : result;
	}

@Override
	public void accept(Visitor<OptimizerNode> visitor) {
		if (visitor.preVisit(this)) {
			if (getPredecessorNode() != null) {
				getPredecessorNode().accept(visitor);
			} else {
				throw new CompilerException();
			}
			for (DagConnection connection : getBroadcastConnections()) {
				connection.getSource().accept(visitor);
			}
			visitor.postVisit(this);
		}
	}

public static CheckpointProperties forCheckpoint(CheckpointRetentionPolicy policy) {
		switch (policy) {
			case NEVER_RETAIN_AFTER_TERMINATION:
				return CHECKPOINT_NEVER_RETAINED;
			case RETAIN_ON_FAILURE:
				return CHECKPOINT_RETAINED_ON_FAILURE;
			case RETAIN_ON_CANCELLATION:
				return CHECKPOINT_RETAINED_ON_CANCELLATION;
			default:
				throw new IllegalArgumentException("unknown policy: " + policy);
		}
	}

