private Mapping extractProjectsAndMapping(
		Aggregate aggregate,
		RelNode input,
		RelBuilder relBuilder) {

		// Compute which input fields are used.
		final ImmutableBitSet.Builder inputFieldsUsed = getInputFieldUsed(aggregate, input);

		final List<RexNode> projects = new ArrayList<>();
		final Mapping mapping =
			Mappings.create(MappingType.INVERSE_SURJECTION,
				aggregate.getInput().getRowType().getFieldCount(),
				inputFieldsUsed.cardinality());
		int j = 0;
		for (int i : inputFieldsUsed.build()) {
			projects.add(relBuilder.field(i));
			mapping.set(i, j++);
		}

		if (input instanceof Project) {
			// this will not create trivial projects
			relBuilder.project(projects);
		} else {
			relBuilder.project(projects, Collections.emptyList(), true);
		}

		return mapping;
	}

private ImmutableBitSet.Builder getInputFieldUsed(Aggregate aggregate, RelNode input) {
		// 1. group fields are always used
		final ImmutableBitSet.Builder inputFieldsUsed =
			aggregate.getGroupSet().rebuild();
		// 2. agg functions
		for (AggregateCall aggCall : aggregate.getAggCallList()) {
			for (int i : aggCall.getArgList()) {
				inputFieldsUsed.set(i);
			}
			if (aggCall.filterArg >= 0) {
				inputFieldsUsed.set(aggCall.filterArg);
			}
		}
		// 3. window time field if the aggregate is a group window aggregate.
		if (aggregate instanceof LogicalWindowAggregate) {
			inputFieldsUsed.set(getWindowTimeFieldIndex((LogicalWindowAggregate) aggregate, input));
		}
		return inputFieldsUsed;
	}

public static long calculateCutoffMB(Configuration config, long containerMemoryMB) {
		Preconditions.checkArgument(containerMemoryMB > 0);

		// (1) check cutoff ratio
		final float memoryCutoffRatio = config.getFloat(
			ResourceManagerOptions.CONTAINERIZED_HEAP_CUTOFF_RATIO);

		if (memoryCutoffRatio >= 1 || memoryCutoffRatio <= 0) {
			throw new IllegalArgumentException("The configuration value '"
				+ ResourceManagerOptions.CONTAINERIZED_HEAP_CUTOFF_RATIO.key() + "' must be between 0 and 1. Value given="
				+ memoryCutoffRatio);
		}

		// (2) check min cutoff value
		final int minCutoff = config.getInteger(
			ResourceManagerOptions.CONTAINERIZED_HEAP_CUTOFF_MIN);

		if (minCutoff >= containerMemoryMB) {
			throw new IllegalArgumentException("The configuration value '"
				+ ResourceManagerOptions.CONTAINERIZED_HEAP_CUTOFF_MIN.key() + "'='" + minCutoff
				+ "' is larger than the total container memory " + containerMemoryMB);
		}

		// (3) check between heap and off-heap
		long cutoff = (long) (containerMemoryMB * memoryCutoffRatio);
		if (cutoff < minCutoff) {
			cutoff = minCutoff;
		}
		return cutoff;
	}

