private static int parseFraction(String v, int multiplier) {
		int r = 0;
		for (int i = 0; i < v.length(); i++) {
			char c = v.charAt(i);
			int x = c < '0' || c > '9' ? 0 : (c - '0');
			r += multiplier * x;
			if (multiplier < 10) {
				// We're at the last digit. Check for rounding.
				if (i + 1 < v.length()
					&& v.charAt(i + 1) >= '5') {
					++r;
				}
				break;
			}
			multiplier /= 10;
		}
		return r;
	}

private static long firstMondayOfFirstWeek(int year) {
		final long janFirst = ymdToJulian(year, 1, 1);
		final long janFirstDow = floorMod(janFirst + 1, 7); // sun=0, sat=6
		return janFirst + (11 - janFirstDow) % 7 - 3;
	}

public static int unixTimeExtract(TimeUnitRange range, int time) {
		assert time >= 0;
		assert time < MILLIS_PER_DAY;
		switch (range) {
			case HOUR:
				return time / (int) MILLIS_PER_HOUR;
			case MINUTE:
				final int minutes = time / (int) MILLIS_PER_MINUTE;
				return minutes % 60;
			case SECOND:
				final int seconds = time / (int) MILLIS_PER_SECOND;
				return seconds % 60;
			default:
				throw new ValidationException("unit " + range + " can not be applied to time variable");
		}
	}

public static long addMonths(long timestamp, int m) {
		final long millis =
			DateTimeUtils.floorMod(timestamp, DateTimeUtils.MILLIS_PER_DAY);
		timestamp -= millis;
		final long x =
			addMonths((int) (timestamp / DateTimeUtils.MILLIS_PER_DAY), m);
		return x * DateTimeUtils.MILLIS_PER_DAY + millis;
	}

public static int addMonths(int date, int m) {
		int y0 = (int) DateTimeUtils.unixDateExtract(TimeUnitRange.YEAR, date);
		int m0 = (int) DateTimeUtils.unixDateExtract(TimeUnitRange.MONTH, date);
		int d0 = (int) DateTimeUtils.unixDateExtract(TimeUnitRange.DAY, date);
		int y = m / 12;
		y0 += y;
		m0 += m - y * 12;
		int last = lastDay(y0, m0);
		if (d0 > last) {
			d0 = 1;
			if (++m0 > 12) {
				m0 = 1;
				++y0;
			}
		}
		return DateTimeUtils.ymdToUnixDate(y0, m0, d0);
	}

public static int subtractMonths(int date0, int date1) {
		if (date0 < date1) {
			return -subtractMonths(date1, date0);
		}
		// Start with an estimate.
		// Since no month has more than 31 days, the estimate is <= the true value.
		int m = (date0 - date1) / 31;
		for (;;) {
			int date2 = addMonths(date1, m);
			if (date2 >= date0) {
				return m;
			}
			int date3 = addMonths(date1, m + 1);
			if (date3 > date0) {
				return m;
			}
			++m;
		}
	}

public static SingleInputSemanticProperties addSourceFieldOffset(SingleInputSemanticProperties props,
																		int numInputFields, int offset) {

		SingleInputSemanticProperties offsetProps = new SingleInputSemanticProperties();
		if (props.getReadFields(0) != null) {
			FieldSet offsetReadFields = new FieldSet();
			for (int r : props.getReadFields(0)) {
				offsetReadFields = offsetReadFields.addField(r + offset);
			}
			offsetProps.addReadFields(offsetReadFields);
		}
		for (int s = 0; s < numInputFields; s++) {
			FieldSet targetFields = props.getForwardingTargetFields(0, s);
			for (int t : targetFields) {
				offsetProps.addForwardedField(s + offset, t);
			}
		}
		return offsetProps;
	}

