public String getUniqueInternalName(String baseName) {
		int counter = 0;
		String candidate = baseName;
		while (usedNames.contains(candidate)) {
			candidate = baseName + STATE_NAME_DELIM + counter++;
		}
		usedNames.add(candidate);
		return candidate;
	}

