@Override
	public DataSet<Result<K>> runInternal(Graph<K, VV, EV> input)
			throws Exception {
		// u, v, bitmask where u < v
		DataSet<Tuple3<K, K, ByteValue>> filteredByID = input
			.getEdges()
			.map(new OrderByID<>())
				.setParallelism(parallelism)
				.name("Order by ID")
			.groupBy(0, 1)
			.reduceGroup(new ReduceBitmask<>())
				.setParallelism(parallelism)
				.name("Flatten by ID");

		// u, v, (deg(u), deg(v))
		DataSet<Edge<K, Tuple3<EV, Degrees, Degrees>>> pairDegrees = input
			.run(new EdgeDegreesPair<K, VV, EV>()
				.setParallelism(parallelism));

		// u, v, bitmask where deg(u) < deg(v) or (deg(u) == deg(v) and u < v)
		DataSet<Tuple3<K, K, ByteValue>> filteredByDegree = pairDegrees
			.map(new OrderByDegree<>())
				.setParallelism(parallelism)
				.name("Order by degree")
			.groupBy(0, 1)
			.reduceGroup(new ReduceBitmask<>())
				.setParallelism(parallelism)
				.name("Flatten by degree");

		// u, v, w, bitmask where (u, v) and (u, w) are edges in graph
		DataSet<Tuple4<K, K, K, ByteValue>> triplets = filteredByDegree
			.groupBy(0)
			.sortGroup(1, Order.ASCENDING)
			.reduceGroup(new GenerateTriplets<>())
				.name("Generate triplets");

		// u, v, w, bitmask where (u, v), (u, w), and (v, w) are edges in graph
		DataSet<Result<K>> triangles = triplets
			.join(filteredByID, JoinOperatorBase.JoinHint.REPARTITION_HASH_SECOND)
			.where(1, 2)
			.equalTo(0, 1)
			.with(new ProjectTriangles<>())
				.name("Triangle listing");

		if (permuteResults) {
			triangles = triangles
				.flatMap(new PermuteResult<>())
					.name("Permute triangle vertices");
		} else if (sortTriangleVertices.get()) {
			triangles = triangles
				.map(new SortTriangleVertices<>())
					.name("Sort triangle vertices");
		}

		return triangles;
	}

@Override
	public Graph<K, VV, EV> runInternal(Graph<K, VV, EV> input)
			throws Exception {
		// u, d(u)
		DataSet<Vertex<K, LongValue>> vertexDegree = input
			.run(new VertexDegree<K, VV, EV>()
				.setReduceOnTargetId(reduceOnTargetId.get())
				.setParallelism(parallelism));

		// u, d(u) if d(u) > maximumDegree
		DataSet<Tuple1<K>> highDegreeVertices = vertexDegree
			.flatMap(new DegreeFilter<>(maximumDegree))
				.setParallelism(parallelism)
				.name("Filter high-degree vertices");

		JoinHint joinHint = broadcastHighDegreeVertices.get() ? JoinHint.BROADCAST_HASH_SECOND : JoinHint.REPARTITION_HASH_SECOND;

		// Vertices
		DataSet<Vertex<K, VV>> vertices = input
			.getVertices()
			.leftOuterJoin(highDegreeVertices, joinHint)
			.where(0)
			.equalTo(0)
			.with(new ProjectVertex<>())
				.setParallelism(parallelism)
				.name("Project low-degree vertices");

		// Edges
		DataSet<Edge<K, EV>> edges = input
			.getEdges()
			.leftOuterJoin(highDegreeVertices, joinHint)
			.where(reduceOnTargetId.get() ? 1 : 0)
			.equalTo(0)
				.with(new ProjectEdge<>())
				.setParallelism(parallelism)
				.name("Project low-degree edges by " + (reduceOnTargetId.get() ? "target" : "source"))
			.leftOuterJoin(highDegreeVertices, joinHint)
			.where(reduceOnTargetId.get() ? 0 : 1)
			.equalTo(0)
			.with(new ProjectEdge<>())
				.setParallelism(parallelism)
				.name("Project low-degree edges by " + (reduceOnTargetId.get() ? "source" : "target"));

		// Graph
		return Graph.fromDataSet(vertices, edges, input.getContext());
	}

@Nonnull
	MultiTaskSlot createRootSlot(
			SlotRequestId slotRequestId,
			CompletableFuture<? extends SlotContext> slotContextFuture,
			SlotRequestId allocatedSlotRequestId) {
		final MultiTaskSlot rootMultiTaskSlot = new MultiTaskSlot(
			slotRequestId,
			slotContextFuture,
			allocatedSlotRequestId);

		LOG.debug("Create multi task slot [{}] in slot [{}].", slotRequestId, allocatedSlotRequestId);

		allTaskSlots.put(slotRequestId, rootMultiTaskSlot);

		unresolvedRootSlots.put(slotRequestId, rootMultiTaskSlot);

		// add the root node to the set of resolved root nodes once the SlotContext future has
		// been completed and we know the slot's TaskManagerLocation
		slotContextFuture.whenComplete(
			(SlotContext slotContext, Throwable throwable) -> {
				if (slotContext != null) {
					final MultiTaskSlot resolvedRootNode = unresolvedRootSlots.remove(slotRequestId);

					if (resolvedRootNode != null) {
						final AllocationID allocationId = slotContext.getAllocationId();
						LOG.trace("Fulfill multi task slot [{}] with slot [{}].", slotRequestId, allocationId);

						final Map<AllocationID, MultiTaskSlot> innerMap = resolvedRootSlots.computeIfAbsent(
							slotContext.getTaskManagerLocation(),
							taskManagerLocation -> new HashMap<>(4));

						MultiTaskSlot previousValue = innerMap.put(allocationId, resolvedRootNode);
						Preconditions.checkState(previousValue == null);
					}
				} else {
					rootMultiTaskSlot.release(throwable);
				}
			});

		return rootMultiTaskSlot;
	}

