public List<String> params(String name) {
		List<String> values = queryParams.get(name);
		String value = pathParams.get(name);

		if (values == null) {
			return (value == null) ? Collections.<String>emptyList() : Collections.singletonList(value);
		}

		if (value == null) {
			return Collections.unmodifiableList(values);
		} else {
			List<String> aggregated = new ArrayList<String>(values.size() + 1);
			aggregated.addAll(values);
			aggregated.add(value);
			return Collections.unmodifiableList(aggregated);
		}
	}

public final V put(K key, V value) {
		final int hash = hash(key);
		final int slot = indexOf (hash);

		// search the chain from the slot
		for (Entry<K, V> e = table[slot]; e != null; e = e.next) {
			Object k;
			if (e.hashCode == hash && ((k = e.key) == key || key.equals(k))) {
				// found match
				V old = e.value;
				e.value = value;
				return old;
			}
		}

		// no match, insert a new value
		insertNewEntry(hash, key, value, slot);
		return null;
	}

