private static Configuration loadYAMLResource(File file) {
		final Configuration config = new Configuration();

		try (BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(file)))){

			String line;
			int lineNo = 0;
			while ((line = reader.readLine()) != null) {
				lineNo++;
				// 1. check for comments
				String[] comments = line.split("#", 2);
				String conf = comments[0].trim();

				// 2. get key and value
				if (conf.length() > 0) {
					String[] kv = conf.split(": ", 2);

					// skip line with no valid key-value pair
					if (kv.length == 1) {
						LOG.warn("Error while trying to split key and value in configuration file " + file + ":" + lineNo + ": \"" + line + "\"");
						continue;
					}

					String key = kv[0].trim();
					String value = kv[1].trim();

					// sanity check
					if (key.length() == 0 || value.length() == 0) {
						LOG.warn("Error after splitting key and value in configuration file " + file + ":" + lineNo + ": \"" + line + "\"");
						continue;
					}

					LOG.info("Loading configuration property: {}, {}", key, isSensitive(key) ? HIDDEN_CONTENT : value);
					config.setString(key, value);
				}
			}
		} catch (IOException e) {
			throw new RuntimeException("Error parsing YAML configuration.", e);
		}

		return config;
	}

public static boolean isSensitive(String key) {
		Preconditions.checkNotNull(key, "key is null");
		final String keyInLower = key.toLowerCase();
		for (String hideKey : SENSITIVE_KEYS) {
			if (keyInLower.length() >= hideKey.length()
				&& keyInLower.contains(hideKey)) {
				return true;
			}
		}
		return false;
	}

public boolean close() {
		lock.lock();
		try {
			if (open) {
				if (elements.isEmpty()) {
					open = false;
					nonEmpty.signalAll();
					return true;
				} else {
					return false;
				}
			}
			else {
				// already closed
				return true;
			}
		} finally {
			lock.unlock();
		}
	}

public boolean addIfOpen(E element) {
		requireNonNull(element);

		lock.lock();
		try {
			if (open) {
				elements.addLast(element);
				if (elements.size() == 1) {
					nonEmpty.signalAll();
				}
			}
			return open;
		} finally {
			lock.unlock();
		}
	}

public void add(E element) throws IllegalStateException {
		requireNonNull(element);

		lock.lock();
		try {
			if (open) {
				elements.addLast(element);
				if (elements.size() == 1) {
					nonEmpty.signalAll();
				}
			} else {
				throw new IllegalStateException("queue is closed");
			}
		} finally {
			lock.unlock();
		}
	}

