private void tryDenseMode() {

		if (numSpillFiles != 0) {
			return;
		}

		long minKey = Long.MAX_VALUE;
		long maxKey = Long.MIN_VALUE;
		long recordCount = 0;
		for (LongHashPartition p : this.partitionsBeingBuilt) {
			long partitionRecords = p.getBuildSideRecordCount();
			recordCount += partitionRecords;
			if (partitionRecords > 0) {
				if (p.getMinKey() < minKey) {
					minKey = p.getMinKey();
				}
				if (p.getMaxKey() > maxKey) {
					maxKey = p.getMaxKey();
				}
			}
		}

		if (buildSpillRetBufferNumbers != 0) {
			throw new RuntimeException("buildSpillRetBufferNumbers should be 0: " + buildSpillRetBufferNumbers);
		}

		long range = maxKey - minKey + 1;
		if (range <= recordCount * 4 || range <= segmentSize / 8) {

			// try to request memory.
			int buffers = (int) Math.ceil(((double) (range * 8)) / segmentSize);

			// TODO MemoryManager needs to support flexible larger segment, so that the index area of the
			// build side is placed on a segment to avoid the overhead of addressing.
			MemorySegment[] denseBuckets = new MemorySegment[buffers];
			for (int i = 0; i < buffers; i++) {
				MemorySegment seg = getNextBuffer();
				if (seg == null) {
					returnAll(Arrays.asList(denseBuckets));
					return;
				}
				denseBuckets[i] = seg;
				for (int j = 0; j < segmentSize; j += 8) {
					seg.putLong(j, INVALID_ADDRESS);
				}
			}

			denseMode = true;
			LOG.info("LongHybridHashTable: Use dense mode!");
			this.minKey = minKey;
			this.maxKey = maxKey;
			buildSpillReturnBuffers.drainTo(availableMemory);

			ArrayList<MemorySegment> dataBuffers = new ArrayList<>();

			long addressOffset = 0;
			for (LongHashPartition p : this.partitionsBeingBuilt) {
				p.iteratorToDenseBucket(denseBuckets, addressOffset, minKey);
				p.updateDenseAddressOffset(addressOffset);

				dataBuffers.addAll(Arrays.asList(p.getPartitionBuffers()));
				addressOffset += (p.getPartitionBuffers().length << segmentSizeBits);
				returnAll(Arrays.asList(p.getBuckets()));
			}

			this.denseBuckets = denseBuckets;
			this.densePartition = new LongHashPartition(this, buildSideSerializer,
					dataBuffers.toArray(new MemorySegment[dataBuffers.size()]));
			freeCurrent();
		}
	}

@Override
	public RocksDBRestoreResult restore()
		throws IOException, StateMigrationException, RocksDBException {
		openDB();
		for (KeyedStateHandle keyedStateHandle : restoreStateHandles) {
			if (keyedStateHandle != null) {

				if (!(keyedStateHandle instanceof KeyGroupsStateHandle)) {
					throw new IllegalStateException("Unexpected state handle type, " +
						"expected: " + KeyGroupsStateHandle.class +
						", but found: " + keyedStateHandle.getClass());
				}
				this.currentKeyGroupsStateHandle = (KeyGroupsStateHandle) keyedStateHandle;
				restoreKeyGroupsInStateHandle();
			}
		}
		return new RocksDBRestoreResult(this.db, defaultColumnFamilyHandle, nativeMetricMonitor,
			-1, null, null);
	}

private void restoreKeyGroupsInStateHandle()
		throws IOException, StateMigrationException, RocksDBException {
		try {
			currentStateHandleInStream = currentKeyGroupsStateHandle.openInputStream();
			cancelStreamRegistry.registerCloseable(currentStateHandleInStream);
			currentStateHandleInView = new DataInputViewStreamWrapper(currentStateHandleInStream);
			restoreKVStateMetaData();
			restoreKVStateData();
		} finally {
			if (cancelStreamRegistry.unregisterCloseable(currentStateHandleInStream)) {
				IOUtils.closeQuietly(currentStateHandleInStream);
			}
		}
	}

private void restoreKVStateMetaData() throws IOException, StateMigrationException {
		KeyedBackendSerializationProxy<K> serializationProxy = readMetaData(currentStateHandleInView);

		this.keygroupStreamCompressionDecorator = serializationProxy.isUsingKeyGroupCompression() ?
			SnappyStreamCompressionDecorator.INSTANCE : UncompressedStreamCompressionDecorator.INSTANCE;

		List<StateMetaInfoSnapshot> restoredMetaInfos =
			serializationProxy.getStateMetaInfoSnapshots();
		currentStateHandleKVStateColumnFamilies = new ArrayList<>(restoredMetaInfos.size());

		for (StateMetaInfoSnapshot restoredMetaInfo : restoredMetaInfos) {
			RocksDbKvStateInfo registeredStateCFHandle =
				getOrRegisterStateColumnFamilyHandle(null, restoredMetaInfo);
			currentStateHandleKVStateColumnFamilies.add(registeredStateCFHandle.columnFamilyHandle);
		}
	}

private void restoreKVStateData() throws IOException, RocksDBException {
		//for all key-groups in the current state handle...
		try (RocksDBWriteBatchWrapper writeBatchWrapper = new RocksDBWriteBatchWrapper(db)) {
			for (Tuple2<Integer, Long> keyGroupOffset : currentKeyGroupsStateHandle.getGroupRangeOffsets()) {
				int keyGroup = keyGroupOffset.f0;

				// Check that restored key groups all belong to the backend
				Preconditions.checkState(keyGroupRange.contains(keyGroup),
					"The key group must belong to the backend");

				long offset = keyGroupOffset.f1;
				//not empty key-group?
				if (0L != offset) {
					currentStateHandleInStream.seek(offset);
					try (InputStream compressedKgIn = keygroupStreamCompressionDecorator.decorateWithCompression(currentStateHandleInStream)) {
						DataInputViewStreamWrapper compressedKgInputView = new DataInputViewStreamWrapper(compressedKgIn);
						//TODO this could be aware of keyGroupPrefixBytes and write only one byte if possible
						int kvStateId = compressedKgInputView.readShort();
						ColumnFamilyHandle handle = currentStateHandleKVStateColumnFamilies.get(kvStateId);
						//insert all k/v pairs into DB
						boolean keyGroupHasMoreKeys = true;
						while (keyGroupHasMoreKeys) {
							byte[] key = BytePrimitiveArraySerializer.INSTANCE.deserialize(compressedKgInputView);
							byte[] value = BytePrimitiveArraySerializer.INSTANCE.deserialize(compressedKgInputView);
							if (hasMetaDataFollowsFlag(key)) {
								//clear the signal bit in the key to make it ready for insertion again
								clearMetaDataFollowsFlag(key);
								writeBatchWrapper.put(handle, key, value);
								//TODO this could be aware of keyGroupPrefixBytes and write only one byte if possible
								kvStateId = END_OF_KEY_GROUP_MARK
									& compressedKgInputView.readShort();
								if (END_OF_KEY_GROUP_MARK == kvStateId) {
									keyGroupHasMoreKeys = false;
								} else {
									handle = currentStateHandleKVStateColumnFamilies.get(kvStateId);
								}
							} else {
								writeBatchWrapper.put(handle, key, value);
							}
						}
					}
				}
			}
		}
	}

@VisibleForTesting
	static <T> TypeSerializerSchemaCompatibility<T> resolveSchemaCompatibility(
		Schema writerSchema,
		Schema readerSchema) {

		if (Objects.equals(writerSchema, readerSchema)) {
			return TypeSerializerSchemaCompatibility.compatibleAsIs();
		}

		final SchemaPairCompatibility compatibility =
			SchemaCompatibility.checkReaderWriterCompatibility(readerSchema, writerSchema);

		return avroCompatibilityToFlinkCompatibility(compatibility);
	}

public void start() throws Exception {
		synchronized (lock) {
			checkState(!running, "MiniCluster is already running");

			LOG.info("Starting Flink Mini Cluster");
			LOG.debug("Using configuration {}", miniClusterConfiguration);

			final Configuration configuration = miniClusterConfiguration.getConfiguration();
			final boolean useSingleRpcService = miniClusterConfiguration.getRpcServiceSharing() == RpcServiceSharing.SHARED;

			try {
				initializeIOFormatClasses(configuration);

				LOG.info("Starting Metrics Registry");
				metricRegistry = createMetricRegistry(configuration);

				// bring up all the RPC services
				LOG.info("Starting RPC Service(s)");

				AkkaRpcServiceConfiguration akkaRpcServiceConfig = AkkaRpcServiceConfiguration.fromConfiguration(configuration);

				final RpcServiceFactory dispatcherResourceManagreComponentRpcServiceFactory;

				if (useSingleRpcService) {
					// we always need the 'commonRpcService' for auxiliary calls
					commonRpcService = createRpcService(akkaRpcServiceConfig, false, null);
					final CommonRpcServiceFactory commonRpcServiceFactory = new CommonRpcServiceFactory(commonRpcService);
					taskManagerRpcServiceFactory = commonRpcServiceFactory;
					dispatcherResourceManagreComponentRpcServiceFactory = commonRpcServiceFactory;
				} else {
					// we always need the 'commonRpcService' for auxiliary calls
					commonRpcService = createRpcService(akkaRpcServiceConfig, true, null);

					// start a new service per component, possibly with custom bind addresses
					final String jobManagerBindAddress = miniClusterConfiguration.getJobManagerBindAddress();
					final String taskManagerBindAddress = miniClusterConfiguration.getTaskManagerBindAddress();

					dispatcherResourceManagreComponentRpcServiceFactory = new DedicatedRpcServiceFactory(akkaRpcServiceConfig, jobManagerBindAddress);
					taskManagerRpcServiceFactory = new DedicatedRpcServiceFactory(akkaRpcServiceConfig, taskManagerBindAddress);
				}

				RpcService metricQueryServiceRpcService = MetricUtils.startMetricsRpcService(
					configuration,
					commonRpcService.getAddress());
				metricRegistry.startQueryService(metricQueryServiceRpcService, null);

				ioExecutor = Executors.newFixedThreadPool(
					Hardware.getNumberCPUCores(),
					new ExecutorThreadFactory("mini-cluster-io"));
				haServices = createHighAvailabilityServices(configuration, ioExecutor);

				blobServer = new BlobServer(configuration, haServices.createBlobStore());
				blobServer.start();

				heartbeatServices = HeartbeatServices.fromConfiguration(configuration);

				blobCacheService = new BlobCacheService(
					configuration, haServices.createBlobStore(), new InetSocketAddress(InetAddress.getLocalHost(), blobServer.getPort())
				);

				startTaskManagers();

				MetricQueryServiceRetriever metricQueryServiceRetriever = new RpcMetricQueryServiceRetriever(metricRegistry.getMetricQueryServiceRpcService());

				dispatcherResourceManagerComponents.addAll(createDispatcherResourceManagerComponents(
					configuration,
					dispatcherResourceManagreComponentRpcServiceFactory,
					haServices,
					blobServer,
					heartbeatServices,
					metricRegistry,
					metricQueryServiceRetriever,
					new ShutDownFatalErrorHandler()
				));

				resourceManagerLeaderRetriever = haServices.getResourceManagerLeaderRetriever();
				dispatcherLeaderRetriever = haServices.getDispatcherLeaderRetriever();
				webMonitorLeaderRetrievalService = haServices.getWebMonitorLeaderRetriever();

				dispatcherGatewayRetriever = new RpcGatewayRetriever<>(
					commonRpcService,
					DispatcherGateway.class,
					DispatcherId::fromUuid,
					20,
					Time.milliseconds(20L));
				resourceManagerGatewayRetriever = new RpcGatewayRetriever<>(
					commonRpcService,
					ResourceManagerGateway.class,
					ResourceManagerId::fromUuid,
					20,
					Time.milliseconds(20L));
				webMonitorLeaderRetriever = new LeaderRetriever();

				resourceManagerLeaderRetriever.start(resourceManagerGatewayRetriever);
				dispatcherLeaderRetriever.start(dispatcherGatewayRetriever);
				webMonitorLeaderRetrievalService.start(webMonitorLeaderRetriever);
			}
			catch (Exception e) {
				// cleanup everything
				try {
					close();
				} catch (Exception ee) {
					e.addSuppressed(ee);
				}
				throw e;
			}

			// create a new termination future
			terminationFuture = new CompletableFuture<>();

			// now officially mark this as running
			running = true;

			LOG.info("Flink Mini Cluster started successfully");
		}
	}

