	public int compareTo(ValueArray<ByteValue> o) {
		ByteValueArray other = (ByteValueArray) o;

		int min = Math.min(position, other.position);
		for (int i = 0; i < min; i++) {
			int cmp = Byte.compare(data[i], other.data[i]);

			if (cmp != 0) {
