public Collection<String> getAllPaths() throws Exception {
		final String path = "/";

		while (true) {
			Stat stat = client.checkExists().forPath(path);

			if (stat == null) {
				return Collections.emptyList();
			} else {
				try {
					return client.getChildren().forPath(path);
