		}

		release(pathInZooKeeper);

		try {
			client.delete().forPath(path);
		} catch (KeeperException.NotEmptyException ignored) {
			LOG.debug("Could not delete znode {} because it is still locked.", path);
			return false;
		}

		if (stateHandle != null) {
			stateHandle.discardState();
		}

		return true;
	}

