            // 判断hbase表是否存在，不存在则建表
            MappingConfig.HbaseMapping hbaseMapping = config.getHbaseMapping();
            if (!hbaseTemplate.tableExists(hbaseMapping.getHbaseTable())) {
                hbaseTemplate.createTable(hbaseMapping.getHbaseTable(), hbaseMapping.getFamily());
            }
        } catch (Exception e) {
