@Override
    protected CreditCardAuthorizationResult run() {
        // Simulate transitive dependency from CreditCardCommand to GetUserAccountCommand.
        // UserAccount could be injected into this command as an argument (and that would be more accurate)
        // but often in large codebase that ends up not happening and each library fetches common data
        // such as user information directly such as this example.
        UserAccount user = new GetUserAccountCommand(new HttpCookie("mockKey", "mockValueFromHttpRequest")).execute();
        if (user.getAccountType() == 1) {
            // do something
        } else {
            // do something else
        }

        // perform credit card transaction
        Result<Transaction> result = gateway.submit(payment.getCreditCardNumber(),
                String.valueOf(payment.getExpirationMonth()),
                String.valueOf(payment.getExpirationYear()),
                TransactionType.AUTH_CAPTURE, amount, order);

        if (result.isApproved()) {
            return CreditCardAuthorizationResult.createSuccessResponse(result.getTarget().getTransactionId(), result.getTarget().getAuthorizationCode());
        } else if (result.isDeclined()) {
            return CreditCardAuthorizationResult.createFailedResponse(result.getReasonResponseCode() + " : " + result.getResponseText());
        } else {
            // check for duplicate transaction
            if (result.getReasonResponseCode().getResponseReasonCode() == 11) {
                if (result.getTarget().getAuthorizationCode() != null) {
                    // We will treat this as a success as this is telling us we have a successful authorization code
                    // just that we attempted to re-post it again during the 'duplicateWindow' time period.
                    // This is part of the idempotent behavior we require so that we can safely timeout and/or fail and allow
                    // client applications to re-attempt submitting a credit card transaction for the same order again.
                    // In those cases if the client saw a failure but the transaction actually succeeded, this will capture the
                    // duplicate response and behave to the client as a success.
                    return CreditCardAuthorizationResult.createDuplicateSuccessResponse(result.getTarget().getTransactionId(), result.getTarget().getAuthorizationCode());
                }
            }
            // handle all other errors
            return CreditCardAuthorizationResult.createFailedResponse(result.getReasonResponseCode() + " : " + result.getResponseText());
            /**
             * NOTE that in this use case we do not throw an exception for an "error" as this type of error from the service is not a system error,
             * but a legitimate usage problem successfully delivered back from the service.
             * 
             * Unexpected errors will be allowed to throw RuntimeExceptions.
             * 
             * The HystrixBadRequestException could potentially be used here, but with such a complex set of errors and reason codes
             * it was chosen to stick with the response object approach rather than using an exception.
             */
        }
    }

void addExecutedCommand(HystrixInvokableInfo<?> command) {
        if (!allExecutedCommands.offer(command)) {
            // see RequestLog: Reduce Chance of Memory Leak https://github.com/Netflix/Hystrix/issues/53
            logger.warn("RequestLog ignoring command after reaching limit of " + MAX_STORAGE + ". See https://github.com/Netflix/Hystrix/issues/53 for more information.");
        }

        // TODO remove this when deprecation completed
        if (command instanceof HystrixCommand) {
            @SuppressWarnings("rawtypes")
            HystrixCommand<?> _c = (HystrixCommand) command;
            if (!executedCommands.offer(_c)) {
                // see RequestLog: Reduce Chance of Memory Leak https://github.com/Netflix/Hystrix/issues/53
                logger.warn("RequestLog ignoring command after reaching limit of " + MAX_STORAGE + ". See https://github.com/Netflix/Hystrix/issues/53 for more information.");
            }
        }
    }

public String getExecutedCommandsAsString() {
        try {
            LinkedHashMap<String, Integer> aggregatedCommandsExecuted = new LinkedHashMap<String, Integer>();
            Map<String, Integer> aggregatedCommandExecutionTime = new HashMap<String, Integer>();

            StringBuilder builder = new StringBuilder();
            int estimatedLength = 0;
            for (HystrixInvokableInfo<?> command : allExecutedCommands) {
                builder.setLength(0);
                builder.append(command.getCommandKey().name());

                List<HystrixEventType> events = new ArrayList<HystrixEventType>(command.getExecutionEvents());
                if (events.size() > 0) {
                    Collections.sort(events);
                    //replicate functionality of Arrays.toString(events.toArray()) to append directly to existing StringBuilder
                    builder.append("[");
                    for (HystrixEventType event : events) {
                        switch (event) {
                            case EMIT:
                                int numEmissions = command.getNumberEmissions();
                                if (numEmissions > 1) {
                                    builder.append(event).append("x").append(numEmissions).append(", ");
                                } else {
                                    builder.append(event).append(", ");
                                }
                                break;
                            case FALLBACK_EMIT:
                                int numFallbackEmissions = command.getNumberFallbackEmissions();
                                if (numFallbackEmissions > 1) {
                                    builder.append(event).append("x").append(numFallbackEmissions).append(", ");
                                } else {
                                    builder.append(event).append(", ");
                                }
                                break;
                            default:
                                builder.append(event).append(", ");
                        }
                    }
                    builder.setCharAt(builder.length() - 2, ']');
                    builder.setLength(builder.length() - 1);
                } else {
                    builder.append("[Executed]");
                }

                String display = builder.toString();
                estimatedLength += display.length() + 12; //add 12 chars to display length for appending totalExecutionTime and count below
                Integer counter = aggregatedCommandsExecuted.get(display);
                if( counter != null){
                    aggregatedCommandsExecuted.put(display, counter + 1);
                } else {
                    // add it
                    aggregatedCommandsExecuted.put(display, 1);
                }                

                int executionTime = command.getExecutionTimeInMilliseconds();
                if (executionTime < 0) {
                    // do this so we don't create negative values or subtract values
                    executionTime = 0;
                }
                counter = aggregatedCommandExecutionTime.get(display);
                if( counter != null && executionTime > 0){
                    // add to the existing executionTime (sum of executionTimes for duplicate command displayNames)
                    aggregatedCommandExecutionTime.put(display, aggregatedCommandExecutionTime.get(display) + executionTime);
                } else {
                    // add it
                    aggregatedCommandExecutionTime.put(display, executionTime);
                }

            }

            builder.setLength(0);
            builder.ensureCapacity(estimatedLength);
            for (String displayString : aggregatedCommandsExecuted.keySet()) {
                if (builder.length() > 0) {
                    builder.append(", ");
                }
                builder.append(displayString);

                int totalExecutionTime = aggregatedCommandExecutionTime.get(displayString);
                builder.append("[").append(totalExecutionTime).append("ms]");

                int count = aggregatedCommandsExecuted.get(displayString);
                if (count > 1) {
                    builder.append("x").append(count);
                }
            }
            return builder.toString();
        } catch (Exception e) {
            logger.error("Failed to create HystrixRequestLog response header string.", e);
            // don't let this cause the entire app to fail so just return "Unknown"
            return "Unknown";
        }
    }

public void addValue(int... value) {
        /* no-op if disabled */
        if (!enabled.get())
            return;

        for (int v : value) {
            try {
                getCurrentBucket().data.addValue(v);
            } catch (Exception e) {
                logger.error("Failed to add value: " + v, e);
            }
        }
    }

