private void push(JSONObject jo) throws JSONException {
    if (this.top >= maxdepth) {
      throw new JSONException("Nesting too deep.");
    }
    this.stack[this.top] = jo;
    this.mode = jo == null ? 'a' : 'k';
    this.top += 1;
  }

