            var cause = (Throwable) null;
            if (e instanceof InvokerInvocationException) {
                cause = e.getCause();
            } else {
                cause = e;
            }
            if (failOnError) {
                throw cause;
            }
            LOGGER.error(cause.getMessage(), cause);
        }
        return null;
    }

