@SneakyThrows
    public static ZonedDateTime getDateTime() {
        val clazz = CasVersion.class;
        val resource = clazz.getResource(clazz.getSimpleName() + ".class");
        if ("file".equals(resource.getProtocol())) {
            return DateTimeUtils.zonedDateTimeOf(new File(resource.toURI()).lastModified());
        }
        if ("jar".equals(resource.getProtocol())) {
            val path = resource.getPath();
            val file = new File(path.substring(JAR_PROTOCOL_STARTING_INDEX, path.indexOf('!')));
            return DateTimeUtils.zonedDateTimeOf(file.lastModified());
        }
        if ("vfs".equals(resource.getProtocol())) {
            val file = new VfsResource(resource.openConnection().getContent()).getFile();
            return DateTimeUtils.zonedDateTimeOf(file.lastModified());
        }
        LOGGER.warn("Unhandled url protocol: [{}] resource: [{}]", resource.getProtocol(), resource);
        return ZonedDateTime.now(ZoneOffset.UTC);
    }

@ShellMethod(key = "validate-service", value = "Validate a given JSON/YAML service definition by path or directory")
    public static void validateService(
        @ShellOption(value = {"file"},
            help = "Path to the JSON/YAML service definition file") final String file,
        @ShellOption(value = {"directory"},
            help = "Path to the JSON/YAML service definitions directory",
            defaultValue = "/etc/cas/services") final String directory) {

        if (StringUtils.isBlank(file) && StringUtils.isBlank(directory)) {
            LOGGER.warn("Either file or directory must be specified");
            return;
        }

        if (StringUtils.isNotBlank(file)) {
            val filePath = new File(file);
            validate(filePath);
            return;
        }
        if (StringUtils.isNotBlank(directory)) {
            val directoryPath = new File(directory);
            if (directoryPath.isDirectory()) {
                FileUtils.listFiles(directoryPath, new String[]{"json", "yml"}, false).forEach(ValidateRegisteredServiceCommand::validate);
            }
            return;
        }

    }

