@VisibleForTesting
  static List<IndexIngestionSpec> createIngestionSchema(
      final TaskToolbox toolbox,
      final SegmentProvider segmentProvider,
      final PartitionConfigurationManager partitionConfigurationManager,
      @Nullable final DimensionsSpec dimensionsSpec,
      @Nullable final AggregatorFactory[] metricsSpec,
      @Nullable final Boolean keepSegmentGranularity,
      @Nullable final Granularity segmentGranularity,
      final ObjectMapper jsonMapper,
      final CoordinatorClient coordinatorClient,
      final SegmentLoaderFactory segmentLoaderFactory,
      final RetryPolicyFactory retryPolicyFactory
  ) throws IOException, SegmentLoadingException
  {
    Pair<Map<DataSegment, File>, List<TimelineObjectHolder<String, DataSegment>>> pair = prepareSegments(
        toolbox,
        segmentProvider
    );
    final Map<DataSegment, File> segmentFileMap = pair.lhs;
    final List<TimelineObjectHolder<String, DataSegment>> timelineSegments = pair.rhs;

    if (timelineSegments.size() == 0) {
      return Collections.emptyList();
    }

    // find metadata for interval
    final List<Pair<QueryableIndex, DataSegment>> queryableIndexAndSegments = loadSegments(
        timelineSegments,
        segmentFileMap,
        toolbox.getIndexIO()
    );

    final IndexTuningConfig compactionTuningConfig = partitionConfigurationManager.computeTuningConfig(
        queryableIndexAndSegments
    );

    if (segmentGranularity == null) {
      if (keepSegmentGranularity != null && !keepSegmentGranularity) {
        // all granularity
        final DataSchema dataSchema = createDataSchema(
            segmentProvider.dataSource,
            segmentProvider.interval,
            queryableIndexAndSegments,
            dimensionsSpec,
            metricsSpec,
            Granularities.ALL,
            jsonMapper
        );

        return Collections.singletonList(
            new IndexIngestionSpec(
                dataSchema,
                createIoConfig(
                    toolbox,
                    dataSchema,
                    segmentProvider.interval,
                    coordinatorClient,
                    segmentLoaderFactory,
                    retryPolicyFactory
                ),
                compactionTuningConfig
            )
        );
      } else {
        // original granularity
        final Map<Interval, List<Pair<QueryableIndex, DataSegment>>> intervalToSegments = new TreeMap<>(
            Comparators.intervalsByStartThenEnd()
        );
        //noinspection ConstantConditions
        queryableIndexAndSegments.forEach(
            p -> intervalToSegments.computeIfAbsent(p.rhs.getInterval(), k -> new ArrayList<>())
                                   .add(p)
        );

        final List<IndexIngestionSpec> specs = new ArrayList<>(intervalToSegments.size());
        for (Entry<Interval, List<Pair<QueryableIndex, DataSegment>>> entry : intervalToSegments.entrySet()) {
          final Interval interval = entry.getKey();
          final List<Pair<QueryableIndex, DataSegment>> segmentsToCompact = entry.getValue();
          final DataSchema dataSchema = createDataSchema(
              segmentProvider.dataSource,
              interval,
              segmentsToCompact,
              dimensionsSpec,
              metricsSpec,
              GranularityType.fromPeriod(interval.toPeriod()).getDefaultGranularity(),
              jsonMapper
          );

          specs.add(
              new IndexIngestionSpec(
                  dataSchema,
                  createIoConfig(
                      toolbox,
                      dataSchema,
                      interval,
                      coordinatorClient,
                      segmentLoaderFactory,
                      retryPolicyFactory
                  ),
                  compactionTuningConfig
              )
          );
        }

        return specs;
      }
    } else {
      if (keepSegmentGranularity != null && keepSegmentGranularity) {
        // error
        throw new ISE("segmentGranularity[%s] and keepSegmentGranularity can't be used together", segmentGranularity);
      } else {
        // given segment granularity
        final DataSchema dataSchema = createDataSchema(
            segmentProvider.dataSource,
            segmentProvider.interval,
            queryableIndexAndSegments,
            dimensionsSpec,
            metricsSpec,
            segmentGranularity,
            jsonMapper
        );

        return Collections.singletonList(
            new IndexIngestionSpec(
                dataSchema,
                createIoConfig(
                    toolbox,
                    dataSchema,
                    segmentProvider.interval,
                    coordinatorClient,
                    segmentLoaderFactory,
                    retryPolicyFactory
                ),
                compactionTuningConfig
            )
        );
      }
    }
  }

@Override
  public Node[] pickSeeds(List<Node> nodes)
  {
    int[] optimalIndices = new int[2];
    int numDims = nodes.get(0).getNumDims();

    double bestNormalized = 0.0;
    for (int i = 0; i < numDims; i++) {
      float minCoord = Float.POSITIVE_INFINITY;
      float maxCoord = Float.NEGATIVE_INFINITY;
      float lowestHighside = Float.POSITIVE_INFINITY;
      float highestLowSide = Float.NEGATIVE_INFINITY;
      int highestLowSideIndex = 0;
      int lowestHighSideIndex = 0;

      int counter = 0;
      for (Node node : nodes) {
        minCoord = Math.min(minCoord, node.getMinCoordinates()[i]);
        maxCoord = Math.max(maxCoord, node.getMaxCoordinates()[i]);

        if (node.getMinCoordinates()[i] > highestLowSide) {
          highestLowSide = node.getMinCoordinates()[i];
          highestLowSideIndex = counter;
        }
        if (node.getMaxCoordinates()[i] < lowestHighside) {
          lowestHighside = node.getMaxCoordinates()[i];
          lowestHighSideIndex = counter;
        }

        counter++;
      }
      double normalizedSeparation = (highestLowSideIndex == lowestHighSideIndex) ? -1.0 :
                                    Math.abs((highestLowSide - lowestHighside) / (maxCoord - minCoord));
      if (normalizedSeparation > bestNormalized) {
        optimalIndices[0] = highestLowSideIndex;
        optimalIndices[1] = lowestHighSideIndex;
        bestNormalized = normalizedSeparation;
      }
    }

    // Didn't actually find anything, just return first 2 children
    if (bestNormalized == 0) {
      optimalIndices[0] = 0;
      optimalIndices[1] = 1;
    }

    int indexToRemove1 = Math.min(optimalIndices[0], optimalIndices[1]);
    int indexToRemove2 = Math.max(optimalIndices[0], optimalIndices[1]);
    return new Node[]{nodes.remove(indexToRemove1), nodes.remove(indexToRemove2 - 1)};
  }

