When a new worker appears, listeners are registered for status changes associated with tasks assigned to
the worker. Status changes indicate the creation or completion of a task.
The RemoteTaskRunner updates state according to these changes.

@param worker contains metadata for a worker that has appeared in ZK

@return future that will contain a fully initialized worker

code:
private void updateWorker(final Worker worker)
  {
    final ZkWorker zkWorker = zkWorkers.get(worker.getHost());
    if (zkWorker != null) {
      log.info("Worker[%s] updated its announcement from[%s] to[%s].", worker.getHost(), zkWorker.getWorker(), worker);
      zkWorker.setWorker(worker);
    } else {
      log.warn(
          "WTF, worker[%s] updated its announcement but we didn't have a ZkWorker for it. Ignoring.",
          worker.getHost()
      );
    }
  }

private void removeWorker(final Worker worker)
  {
    log.info("Kaboom! Worker[%s] removed!", worker.getHost());

    final ZkWorker zkWorker = zkWorkers.get(worker.getHost());
    if (zkWorker != null) {
      try {
        scheduleTasksCleanupForWorker(worker.getHost(), getAssignedTasks(worker));
      }
      catch (Exception e) {
        throw new RuntimeException(e);
      }
      finally {
        try {
          zkWorker.close();
        }
        catch (Exception e) {
          log.error(e, "Exception closing worker[%s]!", worker.getHost());
        }
        zkWorkers.remove(worker.getHost());
        checkBlackListedNodes();
      }
    }
    lazyWorkers.remove(worker.getHost());
  }

private void scheduleTasksCleanupForWorker(final String worker, final List<String> tasksToFail)
  {
    // This method is only called from the PathChildrenCache event handler, so this may look like a race,
    // but is actually not.
    cancelWorkerCleanup(worker);

    final ListenableScheduledFuture<?> cleanupTask = cleanupExec.schedule(
        new Runnable()
        {
          @Override
          public void run()
          {
            log.info("Running scheduled cleanup for Worker[%s]", worker);
            try {
              for (String assignedTask : tasksToFail) {
                String taskPath = JOINER.join(indexerZkConfig.getTasksPath(), worker, assignedTask);
                String statusPath = JOINER.join(indexerZkConfig.getStatusPath(), worker, assignedTask);
                if (cf.checkExists().forPath(taskPath) != null) {
                  cf.delete().guaranteed().forPath(taskPath);
                }

                if (cf.checkExists().forPath(statusPath) != null) {
                  cf.delete().guaranteed().forPath(statusPath);
                }

                log.info("Failing task[%s]", assignedTask);
                RemoteTaskRunnerWorkItem taskRunnerWorkItem = runningTasks.remove(assignedTask);
                if (taskRunnerWorkItem != null) {
                  taskRunnerWorkItem.setResult(TaskStatus.failure(assignedTask));
                  TaskRunnerUtils.notifyStatusChanged(listeners, assignedTask, TaskStatus.failure(assignedTask));
                } else {
                  log.warn("RemoteTaskRunner has no knowledge of task[%s]", assignedTask);
                }
              }

              // worker is gone, remove worker task status announcements path.
              String workerStatusPath = JOINER.join(indexerZkConfig.getStatusPath(), worker);
              if (cf.checkExists().forPath(workerStatusPath) != null) {
                cf.delete().guaranteed().forPath(JOINER.join(indexerZkConfig.getStatusPath(), worker));
              }
            }
            catch (Exception e) {
              log.makeAlert("Exception while cleaning up worker[%s]", worker).emit();
              throw new RuntimeException(e);
            }
          }
        },
        config.getTaskCleanupTimeout().toStandardDuration().getMillis(),
        TimeUnit.MILLISECONDS
    );

    removedWorkerCleanups.put(worker, cleanupTask);

    // Remove this entry from removedWorkerCleanups when done, if it's actually the one in there.
    Futures.addCallback(
        cleanupTask,
        new FutureCallback<Object>()
        {
          @Override
          public void onSuccess(Object result)
          {
            removedWorkerCleanups.remove(worker, cleanupTask);
          }

          @Override
          public void onFailure(Throwable t)
          {
            removedWorkerCleanups.remove(worker, cleanupTask);
          }
        }
    );
  }

long calculateDelta()
  {
    try {
      long[] allThreadIds = threadMXBean.getAllThreadIds();
      // the call time depends on number of threads, for 500 threads the estimated time is 4 ms
      long[] bytes = (long[]) getThreadAllocatedBytes.invoke(threadMXBean, (Object) allThreadIds);
      long sum = 0;
      Long2LongMap newResults = new Long2LongOpenHashMap();
      newResults.defaultReturnValue(NO_DATA);
      for (int i = 0; i < allThreadIds.length; i++) {
        long threadId = allThreadIds[i];
        long previous = previousResults.get(threadId);
        long current = bytes[i];
        newResults.put(threadId, current);
        // a) some threads can be terminated and their ids won't be present
        // b) if new threads ids can collide with terminated threads ids then the current allocation can be lesser than
        // before
        if (previous == NO_DATA || previous > current) {
          sum += current;
        } else {
          sum += current - previous;
        }
      }
      previousResults = newResults;
      return sum;
    }
    catch (ReflectiveOperationException e) {
      log.error(e, "Cannot calculate delta"); // it doesn't make sense after initialization is complete
    }
    return 0;
  }

private DataSegment mergeAndPush(final SegmentIdWithShardSpec identifier, final Sink sink, final boolean useUniquePath)
  {
    // Bail out if this sink is null or otherwise not what we expect.
    if (sinks.get(identifier) != sink) {
      log.warn("Sink for segment[%s] no longer valid, bailing out of mergeAndPush.", identifier);
      return null;
    }

    // Use a descriptor file to indicate that pushing has completed.
    final File persistDir = computePersistDir(identifier);
    final File mergedTarget = new File(persistDir, "merged");
    final File descriptorFile = computeDescriptorFile(identifier);

    // Sanity checks
    for (FireHydrant hydrant : sink) {
      if (sink.isWritable()) {
        throw new ISE("WTF?! Expected sink to be no longer writable before mergeAndPush. Segment[%s].", identifier);
      }

      synchronized (hydrant) {
        if (!hydrant.hasSwapped()) {
          throw new ISE("WTF?! Expected sink to be fully persisted before mergeAndPush. Segment[%s].", identifier);
        }
      }
    }

    try {
      if (descriptorFile.exists()) {
        // Already pushed.

        if (useUniquePath) {
          // Don't reuse the descriptor, because the caller asked for a unique path. Leave the old one as-is, since
          // it might serve some unknown purpose.
          log.info("Pushing segment[%s] again with new unique path.", identifier);
        } else {
          log.info("Segment[%s] already pushed.", identifier);
          return objectMapper.readValue(descriptorFile, DataSegment.class);
        }
      }

      log.info("Pushing merged index for segment[%s].", identifier);

      removeDirectory(mergedTarget);

      if (mergedTarget.exists()) {
        throw new ISE("Merged target[%s] exists after removing?!", mergedTarget);
      }

      final File mergedFile;
      List<QueryableIndex> indexes = new ArrayList<>();
      Closer closer = Closer.create();
      try {
        for (FireHydrant fireHydrant : sink) {
          Pair<Segment, Closeable> segmentAndCloseable = fireHydrant.getAndIncrementSegment();
          final QueryableIndex queryableIndex = segmentAndCloseable.lhs.asQueryableIndex();
          log.info("Adding hydrant[%s]", fireHydrant);
          indexes.add(queryableIndex);
          closer.register(segmentAndCloseable.rhs);
        }

        mergedFile = indexMerger.mergeQueryableIndex(
            indexes,
            schema.getGranularitySpec().isRollup(),
            schema.getAggregators(),
            mergedTarget,
            tuningConfig.getIndexSpec(),
            tuningConfig.getSegmentWriteOutMediumFactory()
        );
      }
      catch (Throwable t) {
        throw closer.rethrow(t);
      }
      finally {
        closer.close();
      }

      // Retry pushing segments because uploading to deep storage might fail especially for cloud storage types
      final DataSegment segment = RetryUtils.retry(
          // The appenderator is currently being used for the local indexing task and the Kafka indexing task. For the
          // Kafka indexing task, pushers must use unique file paths in deep storage in order to maintain exactly-once
          // semantics.
          () -> dataSegmentPusher.push(
              mergedFile,
              sink.getSegment().withDimensions(IndexMerger.getMergedDimensionsFromQueryableIndexes(indexes)),
              useUniquePath
          ),
          exception -> exception instanceof Exception,
          5
      );

      objectMapper.writeValue(descriptorFile, segment);

      log.info("Pushed merged index for segment[%s], descriptor is: %s", identifier, segment);

      return segment;
    }
    catch (Exception e) {
      metrics.incrementFailedHandoffs();
      log.warn(e, "Failed to push merged index for segment[%s].", identifier);
      throw new RuntimeException(e);
    }
  }

